import logging
import six


from abc import ABCMeta, abstractmethod


log = logging.getLogger('ute_admin.scope')


@six.add_metaclass(ABCMeta)
class ScopeController(object):
    """Class useful to clean-up library when library becomes out of scope test execution.

    .. code-block:: python

        from ute_common_interface.scope import ScopeController

        class SomeRobotInterface(ScopeController):
            def __init__(self):
                super(SomeRobotInterface, self).__init__()

            def _out_of_scope(self):
                # Some actions to clean-up library e.g. close all connections, dump logs.

    """
    def __init__(self):
        self.ROBOT_LIBRARY_LISTENER = _CloseListener(self._out_of_scope)

    @abstractmethod
    def _out_of_scope(self):
        """Method will define set of actions to clean-up library."""


class _CloseListener(object):

    ROBOT_LISTENER_API_VERSION = 2

    def __init__(self, callback):
        self._callback = callback

    def close(self):
        """Method called when library is out of scope."""
        try:
            if self._callback is not None:
                self._callback()
        except Exception as e:
            log.warning('Exception was raised during library clean-up:\n{}'.format(str(e)))
